// 렉서: 토큰마다 위치를 담는다
function token(type, value, start, end, line, col) {
  return { type, value, start, end, line, col };   // 위치를 함께
}
// 파서: 노드 span = 자식들의 위치를 합친 범위
function makeBin(op, left, right) {
  return { kind: 'bin', op, left, right,
    start: left.start, end: right.end,             // 왼쪽 시작 ~ 오른쪽 끝
    line: left.line, col: left.col };
}
// 오류 보고: 노드·토큰의 위치로 정확한 caret
function reportError(msg, node, source) {
  const srcLine = source.split('\n')[node.line - 1];
  return frame(msg, file, node.line, node.col, srcLine, node.end - node.start);
}

function expect(type, ...expected) {
  const tk = peek();
  if (!expected.includes(tk.type)) {
    // 파서는 여기서 무엇을 기대했는지 안다 → 그대로 전한다
    throw new ParseError(
      `${expected.join(' 또는 ')} 를 기대했는데 '${tk.value}' 가 왔습니다`,
      tk  // 위치도 함께 (3장)
    );
  }
  return next();
}
// primary() 에서: expect('num', 'id', '(')  → 「값이나 ( 기대」

function editDistance(a, b) {              // Levenshtein
  const d = Array.from({length: a.length+1}, (_, i) =>
    [i, ...Array(b.length).fill(0)]);
  for (let j = 0; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++)
      d[i][j] = Math.min(d[i-1][j]+1, d[i][j-1]+1,       // 삭제·삽입
        d[i-1][j-1] + (a[i-1]===b[j-1] ? 0 : 1));         // 교체
  return d[a.length][b.length];
}
function suggest(name, defined) {
  const [best, dist] = defined
    .map(c => [c, editDistance(name, c)])
    .sort((x, y) => x[1] - y[1])[0];
  return dist <= 2 ? best : null;   // 너무 멀면 제안 안 함(엉뚱함 방지)
}
